INSERT INTO games (id, title, tagline, description, genre, price, image_url, cover_banner, rating, release_date, publisher, developer, sys_req_min, sys_req_rec) VALUES
(1, 'VALORANT', 'Defy the limits in a 5v5 character-based tactical shooter.', 'Blend your style and tactical combat on a global, competitive stage. You have 13 rounds to attack and defend your side using sharp gunplay and tactical abilities. Take on foes across Competitive, Premier, and Unrated modes.', 'Tactical FPS', 0.00, 'https://images.unsplash.com/photo-1542751371-adc38448a05e?q=80&w=600&auto=format&fit=crop', 'https://images.unsplash.com/photo-1511512578047-dfb367046420?q=80&w=1200&auto=format&fit=crop', 4.8, '2020-06-02', 'Riot Games', 'Riot Games', 'OS: Windows 10 64-bit | CPU: Intel Core 2 Duo E8400 | RAM: 4 GB | GPU: Intel HD 4000 | Storage: 20 GB', 'OS: Windows 10/11 64-bit | CPU: Intel i3-4150 / Ryzen 3 1200 | RAM: 8 GB | GPU: GTX 730 / AMD R7 240 | Storage: 20 GB SSD'),
(2, 'Counter-Strike 2', 'The premier competitive tactical shooter evolved on Source 2 engine.', 'For over two decades, Counter-Strike has offered an elite competitive experience shaped by millions of players worldwide. Counter-Strike 2 features responsive smoke grenades, sub-tick updates, overhauled audio, and redesigned maps.', 'Tactical FPS', 0.00, 'https://images.unsplash.com/photo-1511512578047-dfb367046420?q=80&w=600&auto=format&fit=crop', 'https://images.unsplash.com/photo-1542751371-adc38448a05e?q=80&w=1200&auto=format&fit=crop', 4.7, '2023-09-27', 'Valve', 'Valve', 'OS: Windows 10 64-bit | CPU: Intel Core i5 750 (4 threads) | RAM: 8 GB | GPU: 1 GB DirectX 11 compatible | Storage: 85 GB', 'OS: Windows 11 64-bit | CPU: Intel Core i7 9700K / Ryzen 7 3700X | RAM: 16 GB | GPU: RTX 2070 / RX 5700 XT | Storage: 85 GB SSD'),
(3, 'Apex Legends', 'Conquer with character in an award-winning free-to-play Hero shooter.', 'Master an ever-growing roster of legendary characters with powerful abilities in strategic squad play. Drop into intense battles, utilize synergies, and claim victory across the Outlands.', 'Battle Royale', 0.00, 'https://images.unsplash.com/photo-1552820728-8b83bb6b773f?q=80&w=600&auto=format&fit=crop', 'https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?q=80&w=1200&auto=format&fit=crop', 4.6, '2019-02-04', 'Electronic Arts', 'Respawn Entertainment', 'OS: 64-bit Windows 10 | CPU: Intel Core i3-6300 3.8GHz | RAM: 6 GB | GPU: NVIDIA GeForce GT 640 | Storage: 75 GB', 'OS: 64-bit Windows 10/11 | CPU: Intel i5 3570K / Ryzen 5 | RAM: 16 GB | GPU: NVIDIA GeForce GTX 970 | Storage: 75 GB SSD'),
(4, 'Call of Duty: Warzone', 'Massive combat arena with dynamic battlefields and lethal loadouts.', 'Welcome to Warzone, the massive free-to-play combat arena featuring Urzikstan and Rebirth Island. Experience top-tier battle royale gameplay with high-impact gun mechanics, killstreaks, and squad-based vehicle combat.', 'Battle Royale', 0.00, 'https://images.unsplash.com/photo-1538481199705-c710c4e965fc?q=80&w=600&auto=format&fit=crop', 'https://images.unsplash.com/photo-1550745165-9bc0b252726f?q=80&w=1200&auto=format&fit=crop', 4.4, '2020-03-10', 'Activision', 'Infinity Ward / Raven Software', 'OS: Windows 10 64 Bit | CPU: Intel Core i5-6600 | RAM: 8 GB | GPU: NVIDIA GeForce GTX 960 | Storage: 125 GB', 'OS: Windows 10/11 64 Bit | CPU: Intel Core i7-8700K | RAM: 16 GB | GPU: NVIDIA RTX 3060 / RX 6600XT | Storage: 125 GB SSD'),
(5, 'Cyberpunk 2077: Phantom Liberty', 'An open-world, action-adventure RPG set in the dark future of Night City.', 'Cyberpunk 2077 is an open-world, action-adventure RPG set in Night City. Play as V, a cyberpunk mercenary, and take on the most powerful forces in the city in a fight for glory and survival. Includes the acclaimed spy-thriller expansion Phantom Liberty.', 'RPG', 59.99, 'https://images.unsplash.com/photo-1542751371-adc38448a05e?q=80&w=600&auto=format&fit=crop', 'https://images.unsplash.com/photo-1509198397868-475647b2a1e5?q=80&w=1200&auto=format&fit=crop', 4.9, '2023-09-26', 'CD PROJEKT RED', 'CD PROJEKT RED', 'OS: 64-bit Windows 10 | CPU: Core i7-6700 or Ryzen 5 1600 | RAM: 12 GB | GPU: GeForce GTX 1060 6GB | Storage: 70 GB SSD', 'OS: 64-bit Windows 11 | CPU: Core i7-12700 or Ryzen 7 7800X3D | RAM: 16 GB | GPU: GeForce RTX 3080 | Storage: 70 GB NVMe SSD'),
(6, 'Elden Ring: Shadow of the Erdtree', 'Rise, Tarnished, and be guided by grace to brandish the Elden Ring.', 'THE CRITICALLY ACCLAIMED FANTASY ACTION RPG. Journey across the Lands Between and the Realm of Shadow. Unravel mysteries, defeat demi-gods, and master deep magic and swordplay in an interconnected open world crafted by FromSoftware.', 'RPG', 59.99, 'https://images.unsplash.com/photo-1518709268805-4e9042af9f23?q=80&w=600&auto=format&fit=crop', 'https://images.unsplash.com/photo-1579546929518-9e396f3cc809?q=80&w=1200&auto=format&fit=crop', 4.9, '2024-06-21', 'Bandai Namco', 'FromSoftware Inc.', 'OS: Windows 10 | CPU: Intel Core i5-8400 | RAM: 12 GB | GPU: GTX 1060 3 GB / RX 580 4 GB | Storage: 80 GB', 'OS: Windows 10/11 | CPU: Intel Core i7-8700K | RAM: 16 GB | GPU: GTX 1070 8 GB / RX Vega 56 | Storage: 80 GB SSD'),
(7, 'Overwatch 2', 'An optimistic future-set free-to-play team-based action game.', 'Overwatch 2 is a critically acclaimed, team-based shooter game set in an optimistic future with an evolving roster of heroes. Team up with friends and jump into exhilarating 5v5 shooter combat across iconic global destinations.', 'Shooter', 0.00, 'https://images.unsplash.com/photo-1560253023-3ec5d502959f?q=80&w=600&auto=format&fit=crop', 'https://images.unsplash.com/photo-1511512578047-dfb367046420?q=80&w=1200&auto=format&fit=crop', 4.3, '2022-10-04', 'Blizzard Entertainment', 'Blizzard Entertainment', 'OS: Windows 10 64-bit | CPU: Intel Core i3 | RAM: 6 GB | GPU: NVIDIA GeForce GTX 600 series | Storage: 50 GB', 'OS: Windows 10/11 64-bit | CPU: Intel Core i7 | RAM: 16 GB | GPU: GeForce GTX 1060 / RTX 2060 | Storage: 50 GB SSD'),
(8, 'EA SPORTS FC 25', 'The World''s Game powered by FC IQ and hyper-realistic match dynamics.', 'EA SPORTS FC 25 gives you more ways to win for the club. Team up in 5v5 Rush, and manage your squad to victory as FC IQ delivers unprecedented tactical control across 19,000 players and 700+ authentic teams.', 'Sports', 69.99, 'https://images.unsplash.com/photo-1508098682722-e99c43a406b2?q=80&w=600&auto=format&fit=crop', 'https://images.unsplash.com/photo-1574629810360-7efbbe195018?q=80&w=1200&auto=format&fit=crop', 4.5, '2024-09-27', 'Electronic Arts', 'EA Vancouver', 'OS: Windows 10 64-Bit | CPU: AMD Ryzen 5 1600 or Intel Core i5 6600K | RAM: 8 GB | GPU: GTX 1050 Ti | Storage: 100 GB', 'OS: Windows 11 64-Bit | CPU: Ryzen 7 2700X or Intel Core i7 6700 | RAM: 16 GB | GPU: GTX 1660 / RX 5600 XT | Storage: 100 GB SSD'),
(9, 'League of Legends', 'The world''s most played competitive multiplayer online battle arena.', 'League of Legends is a team-based strategy game where two teams of five champions face off to destroy the opposing Nexus. Choose from over 160 champions to make epic plays and secure victory.', 'MOBA', 0.00, 'https://images.unsplash.com/photo-1542751371-adc38448a05e?q=80&w=600&auto=format&fit=crop', 'https://images.unsplash.com/photo-1534447677768-be436bb09401?q=80&w=1200&auto=format&fit=crop', 4.8, '2009-10-27', 'Riot Games', 'Riot Games', 'OS: Windows 10/11 | CPU: Intel Core i3-530 | RAM: 4 GB | GPU: GeForce 9600GT / AMD HD 6570 | Storage: 16 GB', 'OS: Windows 10/11 64-bit | CPU: Intel Core i5-3300 | RAM: 8 GB | GPU: GeForce GTX 560 | Storage: 16 GB SSD'),
(10, 'Grand Theft Auto V', 'Explore the sprawling, sun-soaked metropolis of Los Santos.', 'When a young street hustler, a retired bank robber, and a terrifying psychopath get entangled with the criminal underworld, they must pull off a series of dangerous heists to survive in a ruthless city.', 'Action', 29.99, 'https://images.unsplash.com/photo-1511919884226-fd3cad34687c?q=80&w=600&auto=format&fit=crop', 'https://images.unsplash.com/photo-1518173946687-a4c8a383392e?q=80&w=1200&auto=format&fit=crop', 4.9, '2015-04-14', 'Rockstar Games', 'Rockstar North', 'OS: Windows 10 64 Bit | CPU: Intel Core 2 Quad Q6600 @ 2.40GHz | RAM: 8 GB | GPU: NVIDIA 9800 GT 1GB | Storage: 110 GB', 'OS: Windows 10/11 64 Bit | CPU: Intel Core i5 3470 @ 3.2GHz | RAM: 16 GB | GPU: NVIDIA GTX 660 2GB | Storage: 110 GB SSD');
INSERT INTO tournaments (id, title, subtitle, prize_pool, status, start_date, image_url, rulebook) VALUES
(1, 'VALORANT Champions Tour 2026: Berlin', 'The pinnacle of global VALORANT competitive play.', '$1,000,000', 'ongoing', '2026-08-14', 'https://images.unsplash.com/photo-1542751371-adc38448a05e?q=80&w=600&auto=format&fit=crop', 'Official rules: 5v5 team format, double elimination bracket. Single-agent lock per team. Standard official competitive maps only. Teams must check in 30 minutes prior to scheduled match time.'),
(2, 'IEM Katowice 2026: CS2 Major', 'The official world championship tournament for Counter-Strike 2.', '$1,000,000', 'upcoming', '2026-09-05', 'https://images.unsplash.com/photo-1511512578047-dfb367046420?q=80&w=600&auto=format&fit=crop', 'Official rules: 5v5 MR12 competitive rule set. Double elimination playoffs. Anti-cheat client mandatory. Overtime MR3 with $10,000 start cash.'),
(3, 'ALGS Year 5 Championship', 'The world apex showdown for the finest trios on the planet.', '$2,000,000', 'completed', '2026-06-10', 'https://images.unsplash.com/photo-1552820728-8b83bb6b773f?q=80&w=600&auto=format&fit=crop', 'Official rules: Match point format. First team to reach 50 points and subsequently win a match is crowned World Champion.');
